for p in points:
    ga = rosen_grad(p)
    gn = _central_diff_grad(p)
    if np.linalg.norm(gn) > 1e-8:
        # Gradient resolvable by finite differences -> strict relative check.
        rel_err = np.linalg.norm(ga - gn) / np.linalg.norm(gn)
        assert rel_err < 1e-7, f"grad mismatch at {p}: rel err {rel_err}"
    else:
        # Near-stationary point: FD is dominated by round-off, use absolute.
        assert np.linalg.norm(ga - gn) < 1e-8, f"grad mismatch at {p}"
